        payload = {
            "timestamp": datetime.fromtimestamp(record.created, timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z"),
            "level": record.levelname,
            "service": self.service,
            "logger": record.name,
            "message": record.getMessage(),
            **{key: getattr(record, key, None) for key in _fields},
            **{key: getattr(record, key) for key in _details if hasattr(record, key)},
        }
        extra = {key: value for key, value in vars(record).items() if key not in _builtin and key not in payload}
        if extra:
            payload["extra"] = extra
        return json.dumps(payload, ensure_ascii=False, default=str)


