@lru_cache(maxsize=4)
def _trusted_networks(value):
    return tuple(ip_network(part.strip()) for part in value.split(",") if part.strip())


class RequestIdMiddleware:
    def __init__(self, app, service=None):
        self.app, self.service = app, service

    async def __call__(self, scope, receive, send):
        if scope["type"] == "lifespan" and self.service and _active is None:
            setup_logging(self.service)
            try:
                return await self.app(scope, receive, send)
            finally:
                shutdown_logging()
        if scope["type"] != "http":
            return await self.app(scope, receive, send)

        # Only correlation ids are accepted at the public edge. Identity is set after auth.
        headers = dict(scope["headers"])
        supplied = headers.get(b"x-request-id", headers.get(b"x-correlation-id", b""))
        request_id = _request_id(supplied.decode("latin1")) or uuid4().hex
        peer = _ip((scope.get("client") or ("",))[0])
        try:
            if peer and any(ip_address(peer) in network for network in _trusted_networks(os.getenv("TRUSTED_PROXY_CIDRS", ""))):
                peer = _ip(headers.get(b"x-real-ip", b"").decode("latin1")) or peer
        except ValueError:
            pass
        scope.setdefault("state", {})["request_id"] = request_id
        reset = _request.set({"request_id": request_id, "client_ip": peer, "user": ""})
        status, started = 500, time.monotonic()

        async def respond(message):
            nonlocal status
            if message["type"] == "http.response.start":
                status = message["status"]
                response_headers = [(key, value) for key, value in message.get("headers", []) if key != b"x-request-id"]
                response_headers.append((b"x-request-id", request_id.encode("ascii")))
                message = {**message, "headers": response_headers}
            await send(message)

        try:
            await self.app(scope, receive, respond)
        finally:
            route = getattr(scope.get("route"), "path", None) or "[unmatched]"
            method = scope["method"]
            logging.getLogger("http").log(
                logging.ERROR if status >= 500 else logging.INFO, "%s %s", method, route,
                extra={"method": method, "path": route, "status_code": status,
                       "duration_ms": round((time.monotonic() - started) * 1000, 3)},
            )
            _request.reset(reset)
